// services/pdfTemplate.ts

export interface RoomSection {
  name:     string
  products: {
    name:        string
    store:       string | null
    description: string | null
    variations:  string | null
    notes:       string | null
    quantity:    number
    price:       number
    imageBase64: string | null
  }[]
}

// ── Logo branco em base64 (hardcoded) ─────────────────
// Cole aqui o conteúdo completo do logo_b64.txt
const LOGO_WHITE_B64 = 'data:image/png;base64,' // substitua pela string completa

function fmt(value: number): string {
  return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
}

function parseVariationsHtml(json: string | null): string {
  if (!json) return ''
  try {
    const arr: { label: string; value: string }[] = JSON.parse(json)
    return arr
      .map(v => `<span class="var-item">${v.label}: <strong>${v.value}</strong></span>`)
      .join('')
  } catch {
    return ''
  }
}

function productRow(p: RoomSection['products'][number]): string {
  const total      = p.price * p.quantity
  const variations = parseVariationsHtml(p.variations)
  const imgHtml    = p.imageBase64
    ? `<img src="${p.imageBase64}" class="prod-img" />`
    : `<div class="prod-img-empty"></div>`

  return `
    <tr class="prod-row">
      <td class="col-img">${imgHtml}</td>
      <td class="col-name">
        <div class="prod-name">${p.name}</div>
        ${p.store ? `<div class="prod-store">${p.store}</div>` : ''}
      </td>
      <td class="col-desc">
        ${p.description ? `<div class="prod-desc">${p.description}</div>` : ''}
        ${variations    ? `<div class="prod-vars">${variations}</div>`    : ''}
        ${p.notes       ? `<div class="prod-notes">${p.notes}</div>`      : ''}
      </td>
      <td class="col-qty">${p.quantity}</td>
      <td class="col-price">${fmt(p.price)}</td>
      <td class="col-total">${fmt(total)}</td>
    </tr>
  `
}

function roomSection(room: RoomSection): string {
  const subtotal = room.products.reduce((a, p) => a + p.price * p.quantity, 0)
  const rows     = room.products.map(productRow).join('')
  return `
    <div class="room-block">
      <div class="room-header">
        <span class="room-name">${room.name}</span>
        <span class="room-subtotal">${fmt(subtotal)}</span>
      </div>
      <table class="prod-table">
        <thead>
          <tr>
            <th class="col-img">Imagem</th>
            <th class="col-name">Produto</th>
            <th class="col-desc">Descrição</th>
            <th class="col-qty">Qtd</th>
            <th class="col-price">Vl. Unit</th>
            <th class="col-total">Vl. Total</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
  `
}

export function buildPdfHtml(opts: {
  project: {
    name:         string
    client:       string
    client_email: string | null
    description:  string | null
    type:         string | null
  }
  rooms:       RoomSection[]
  coverBase64: string | null
  logoBase64:  string | null
  total:       number
}): string {
  const { project, rooms, coverBase64, total } = opts

  const coverStyle = coverBase64
    ? `background-image: url('${coverBase64}'); background-size: cover; background-position: center;`
    : `background-color: #2C2420;`

  const roomsHtml = rooms.map(roomSection).join('')

  return `
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8" />
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: -apple-system, 'Helvetica Neue', Arial, sans-serif; background: #F5F2ED; color: #1A1A1A; font-size: 11px; }

    .cover {
      width: 100%; min-height: 100vh;
      display: flex; flex-direction: column; justify-content: space-between;
      padding: 60px 56px; position: relative;
      ${coverStyle}
      page-break-after: always;
    }
    .cover::before {
      content: ''; position: absolute; inset: 0;
      background: linear-gradient(to bottom, rgba(28,22,18,0.55) 0%, rgba(28,22,18,0.30) 40%, rgba(28,22,18,0.70) 100%);
    }
    .cover-logo { position: relative; z-index: 1; }
    .cover-logo img { height: 48px; object-fit: contain; }
    .cover-body { position: relative; z-index: 1; }
    .cover-eyebrow { font-size: 10px; letter-spacing: 2.5px; text-transform: uppercase; color: rgba(255,255,255,0.65); margin-bottom: 16px; }
    .cover-title { font-size: 42px; font-weight: 300; color: #FFFFFF; line-height: 1.15; margin-bottom: 8px; letter-spacing: -0.5px; }
    .cover-client { font-size: 15px; color: rgba(255,255,255,0.80); margin-bottom: 6px; }
    .cover-email { font-size: 11px; color: rgba(255,255,255,0.55); }
    .cover-footer {
      position: relative; z-index: 1;
      display: flex; justify-content: space-between; align-items: flex-end;
      border-top: 1px solid rgba(255,255,255,0.20); padding-top: 24px;
    }
    .cover-total-label { font-size: 9px; letter-spacing: 2px; text-transform: uppercase; color: rgba(255,255,255,0.55); margin-bottom: 6px; }
    .cover-total-value { font-size: 32px; font-weight: 300; color: #FFFFFF; letter-spacing: -0.5px; }
    .cover-accent { width: 48px; height: 2px; background: #C4956A; }

    .content { padding: 48px 48px 64px; }
    .page-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 40px; padding-bottom: 16px; border-bottom: 1px solid #DDD8D2; }
    .page-header-title { font-size: 22px; font-weight: 300; color: #1A1A1A; }
    .page-header-sub { font-size: 10px; letter-spacing: 1.5px; text-transform: uppercase; color: #9A8F85; }

    .room-block { margin-bottom: 36px; border: 1px solid #DDD8D2; border-radius: 6px; overflow: hidden; background: #FFFFFF; }
    .room-header { display: flex; justify-content: space-between; align-items: center; padding: 14px 20px; background: #F5F2ED; border-bottom: 1px solid #DDD8D2; }
    .room-name { font-size: 15px; color: #1A1A1A; }
    .room-subtotal { font-size: 16px; font-weight: 300; color: #1A1A1A; }

    .prod-table { width: 100%; border-collapse: collapse; }
    .prod-table thead tr { background: #FAFAF8; }
    .prod-table th { padding: 10px 12px; text-align: left; font-size: 9px; font-weight: 500; letter-spacing: 1.2px; text-transform: uppercase; color: #9A8F85; border-bottom: 1px solid #DDD8D2; }
    .prod-row { border-bottom: 1px solid #EDEAE6; }
    .prod-row:last-child { border-bottom: none; }
    .prod-row td { padding: 14px 12px; vertical-align: top; }

    .col-img   { width: 72px; }
    .col-name  { width: 160px; }
    .col-qty   { width: 40px; text-align: center; }
    .col-price { width: 90px; text-align: right; }
    .col-total { width: 100px; text-align: right; }

    .prod-img { width: 60px; height: 60px; object-fit: cover; border-radius: 4px; display: block; }
    .prod-img-empty { width: 60px; height: 60px; border-radius: 4px; background: #EDEAE6; }
    .prod-name { font-size: 12px; font-weight: 500; color: #1A1A1A; margin-bottom: 3px; }
    .prod-store { font-size: 10px; color: #9A8F85; }
    .prod-desc { font-size: 10.5px; color: #5C5650; line-height: 1.5; margin-bottom: 4px; }
    .prod-vars { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 4px; }
    .var-item { font-size: 9.5px; color: #7A7068; }
    .prod-notes { font-size: 9.5px; color: #9A8F85; font-style: italic; margin-top: 4px; }

    .grand-total { display: flex; justify-content: space-between; align-items: center; background: #1A1A1A; border-radius: 6px; padding: 24px 28px; margin-top: 8px; }
    .grand-total-label { font-size: 9px; letter-spacing: 2px; text-transform: uppercase; color: rgba(255,255,255,0.55); }
    .grand-total-value { font-size: 28px; font-weight: 300; color: #FFFFFF; }

    .footer { margin-top: 48px; padding-top: 20px; border-top: 1px solid #DDD8D2; display: flex; justify-content: space-between; align-items: center; }
    .footer-brand { font-size: 9px; letter-spacing: 2px; text-transform: uppercase; color: #9A8F85; }
    .footer-accent { width: 32px; height: 1.5px; background: #C4956A; }
    .footer-contact { font-size: 9px; color: #9A8F85; text-align: right; }
  </style>
</head>
<body>

  <div class="cover">
    <div class="cover-logo">
      <img src="${LOGO_WHITE_B64}" alt="APduo Arquitetura" />
    </div>
    <div class="cover-body">
      <div class="cover-eyebrow">Proposta de Especificação</div>
      <div class="cover-title">${project.name}</div>
      <div class="cover-client">${project.client}</div>
      ${project.client_email ? `<div class="cover-email">${project.client_email}</div>` : ''}
    </div>
    <div class="cover-footer">
      <div>
        <div class="cover-total-label">Total estimado</div>
        <div class="cover-total-value">${fmt(total)}</div>
      </div>
      <div class="cover-accent"></div>
    </div>
  </div>

  <div class="content">
    <div class="page-header">
      <div>
        <div class="page-header-title">${project.name}</div>
        <div class="page-header-sub">${project.client} — Especificação de produtos</div>
      </div>
      <img src="${LOGO_WHITE_B64}" style="height:28px; opacity:0.25;" />
    </div>

    ${roomsHtml}

    <div class="grand-total">
      <div class="grand-total-label">Total geral do projeto</div>
      <div class="grand-total-value">${fmt(total)}</div>
    </div>

    <div class="footer">
      <div class="footer-brand">APduo Arquitetura</div>
      <div class="footer-accent"></div>
      <div class="footer-contact">contato@apduo.com.br<br/>+55 (21) 96730-0615</div>
    </div>
  </div>

</body>
</html>`.trim()
}